1  import type {RouteProp} from '@react-navigation/native';
     2  import {useRoute} from '@react-navigation/native';
     3  import lodashSortBy from 'lodash/sortBy';
     4  import truncate from 'lodash/truncate';
     5  import React, {useMemo} from 'react';
     6  import {View} from 'react-native';
     7  import type {GestureResponderEvent} from 'react-native';
     8  import {useOnyx} from 'react-native-onyx';
     9  import type {OnyxEntry} from 'react-native-onyx';
    10  import Button from '@components/Button';
    11  import Icon from '@components/Icon';
    12  import * as Expensicons from '@components/Icon/Expensicons';
    13  import {ReceiptScan} from '@components/Icon/Expensicons';
    14  import MoneyRequestSkeletonView from '@components/MoneyRequestSkeletonView';
    15  import MultipleAvatars from '@components/MultipleAvatars';
    16  import OfflineWithFeedback from '@components/OfflineWithFeedback';
    17  import PressableWithoutFeedback from '@components/Pressable/PressableWithoutFeedback';
    18  import ReportActionItemImages from '@components/ReportActionItem/ReportActionItemImages';
    19  import {showContextMenuForReport} from '@components/ShowContextMenuContext';
    20  import Text from '@components/Text';
    21  import useLocalize from '@hooks/useLocalize';
    22  import useResponsiveLayout from '@hooks/useResponsiveLayout';
    23  import useStyleUtils from '@hooks/useStyleUtils';
    24  import useTheme from '@hooks/useTheme';
    25  import useThemeStyles from '@hooks/useThemeStyles';
    26  import useWindowDimensions from '@hooks/useWindowDimensions';
    27  import ControlSelection from '@libs/ControlSelection';
    28  import * as CurrencyUtils from '@libs/CurrencyUtils';
    29  import * as DeviceCapabilities from '@libs/DeviceCapabilities';
    30  import * as IOUUtils from '@libs/IOUUtils';
    31  import Navigation from '@libs/Navigation/Navigation';
    32  import type {TransactionDuplicateNavigatorParamList} from '@libs/Navigation/types';
    33  import * as OptionsListUtils from '@libs/OptionsListUtils';
    34  import * as ReceiptUtils from '@libs/ReceiptUtils';
    35  import * as ReportActionsUtils from '@libs/ReportActionsUtils';
    36  import * as ReportUtils from '@libs/ReportUtils';
    37  import type {TransactionDetails} from '@libs/ReportUtils';
    38  import StringUtils from '@libs/StringUtils';
    39  import * as TransactionUtils from '@libs/TransactionUtils';
    40  import ViolationsUtils from '@libs/Violations/ViolationsUtils';
    41  import variables from '@styles/variables';
    42  import * as PaymentMethods from '@userActions/PaymentMethods';
    43  import * as Report from '@userActions/Report';
    44  import * as Transaction from '@userActions/Transaction';
    45  import CONST from '@src/CONST';
    46  import ONYXKEYS from '@src/ONYXKEYS';
    47  import ROUTES from '@src/ROUTES';
    48  import SCREENS from '@src/SCREENS';
    49  import type {OriginalMessageIOU} from '@src/types/onyx/OriginalMessage';
    50  import {isEmptyObject} from '@src/types/utils/EmptyObject';
    51  import type {MoneyRequestPreviewProps, PendingMessageProps} from './types';
    52
    53  function MoneyRequestPreviewContent({
    54      isBillSplit,
    55      action,
    56      contextMenuAnchor,
    57      chatReportID,
    58      reportID,
    59      onPreviewPressed,
    60      containerStyles,
    61      checkIfContextMenuActive = () => {},
    62      shouldShowPendingConversionMessage = false,
    63      isHovered = false,
    64      isWhisper = false,
    65      shouldDisplayContextMenu = true,
    66      iouReportID,
    67  }: MoneyRequestPreviewProps) {
    68      const theme = useTheme();
    69      const styles = useThemeStyles();
    70      const StyleUtils = useStyleUtils();
    71      const {translate} = useLocalize();
    72      const {windowWidth} = useWindowDimensions();
    73      const route = useRoute<RouteProp<TransactionDuplicateNavigatorParamList, typeof SCREENS.TRANSACTION_DUPLICATE.REVIEW>>();
    74      const {shouldUseNarrowLayout} = useResponsiveLayout();
    75      const [personalDetails] = useOnyx(ONYXKEYS.PERSONAL_DETAILS_LIST);
    76      const [chatReport] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT}${chatReportID || '-1'}`);
    77      const [session] = useOnyx(ONYXKEYS.SESSION);
    78      const [iouReport] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT}${iouReportID || '-1'}`);
    79
    80      const isMoneyRequestAction = ReportActionsUtils.isMoneyRequestAction(action);
    81      const transactionID = isMoneyRequestAction ? ReportActionsUtils.getOriginalMessage(action)?.IOUTransactionID : '-1';
    82      const [transaction] = useOnyx(`${ONYXKEYS.COLLECTION.TRANSACTION}${transactionID}`);
    83      const [walletTerms] = useOnyx(ONYXKEYS.WALLET_TERMS);
    84      const [transactionViolations] = useOnyx(ONYXKEYS.COLLECTION.TRANSACTION_VIOLATIONS);
    85
    86      const sessionAccountID = session?.accountID;
    87      const managerID = iouReport?.managerID ?? -1;
    88      const ownerAccountID = iouReport?.ownerAccountID ?? -1;
    89      const isPolicyExpenseChat = ReportUtils.isPolicyExpenseChat(chatReport);
    90
    91      const participantAccountIDs =
    92          ReportActionsUtils.isMoneyRequestAction(action) && isBillSplit ? ReportActionsUtils.getOriginalMessage(action)?.participantAccountIDs ?? [] : [managerID, ownerAccountID];
    93      const participantAvatars = OptionsListUtils.getAvatarsForAccountIDs(participantAccountIDs, personalDetails ?? {});
    94      const sortedParticipantAvatars = lodashSortBy(participantAvatars, (avatar) => avatar.id);
    95      if (isPolicyExpenseChat && isBillSplit) {
    96          sortedParticipantAvatars.push(ReportUtils.getWorkspaceIcon(chatReport));
    97      }
    98
    99      // Pay button should only be visible to the manager of the report.
   100      const isCurrentUserManager = managerID === sessionAccountID;
   101
   102      const {
   103          amount: requestAmount,
   104          currency: requestCurrency,
   105          comment: requestComment,
   106          merchant,
   107      } = useMemo<Partial<TransactionDetails>>(() => ReportUtils.getTransactionDetails(transaction) ?? {}, [transaction]);
   108
   109      const description = truncate(StringUtils.lineBreaksToSpaces(requestComment), {length: CONST.REQUEST_PREVIEW.MAX_LENGTH});
   110      const requestMerchant = truncate(merchant, {length: CONST.REQUEST_PREVIEW.MAX_LENGTH});
   111      const hasReceipt = TransactionUtils.hasReceipt(transaction);
   112      const isScanning = hasReceipt && TransactionUtils.isReceiptBeingScanned(transaction);
   113      const isOnHold = TransactionUtils.isOnHold(transaction);
   114      const isSettlementOrApprovalPartial = !!iouReport?.pendingFields?.partial;
   115      const isPartialHold = isSettlementOrApprovalPartial && isOnHold;
   116      const hasViolations = TransactionUtils.hasViolation(transaction?.transactionID ?? '-1', transactionViolations);
   117      const hasNoticeTypeViolations = TransactionUtils.hasNoticeTypeViolation(transaction?.transactionID ?? '-1', transactionViolations) && ReportUtils.isPaidGroupPolicy(iouReport);
   118      const hasFieldErrors = TransactionUtils.hasMissingSmartscanFields(transaction);
   119      const isDistanceRequest = TransactionUtils.isDistanceRequest(transaction);
   120      const isFetchingWaypointsFromServer = TransactionUtils.isFetchingWaypointsFromServer(transaction);
   121      const isCardTransaction = TransactionUtils.isCardTransaction(transaction);
   122      const isSettled = ReportUtils.isSettled(iouReport?.reportID);
   123      const isApproved = ReportUtils.isReportApproved(iouReport);
   124      const isDeleted = action?.pendingAction === CONST.RED_BRICK_ROAD_PENDING_ACTION.DELETE;
   125      const isReviewDuplicateTransactionPage = route.name === SCREENS.TRANSACTION_DUPLICATE.REVIEW;
   126
   127      const isFullySettled = isSettled && !isSettlementOrApprovalPartial;
   128      const isFullyApproved = isApproved && !isSettlementOrApprovalPartial;
   129
   130      // Get transaction violations for given transaction id from onyx, find duplicated transactions violations and get duplicates
   131      const allDuplicates = useMemo(
   132          () =>
   133              transactionViolations?.[`${ONYXKEYS.COLLECTION.TRANSACTION_VIOLATIONS}${transaction?.transactionID}`]?.find(
   134                  (violation) => violation.name === CONST.VIOLATIONS.DUPLICATED_TRANSACTION,
   135              )?.data?.duplicates ?? [],
   136          [transaction?.transactionID, transactionViolations],
   137      );
   138
   139      // Remove settled transactions from duplicates
   140      const duplicates = useMemo(() => TransactionUtils.removeSettledAndApprovedTransactions(allDuplicates), [allDuplicates]);
   141
   142      // When there are no settled transactions in duplicates, show the "Keep this one" button
   143      const shouldShowKeepButton = !!(allDuplicates.length && duplicates.length && allDuplicates.length === duplicates.length);
   144
   145      const hasDuplicates = duplicates.length > 0;
   146
   147      const shouldShowRBR = hasNoticeTypeViolations || hasViolations || hasFieldErrors || (!isFullySettled && !isFullyApproved && isOnHold) || hasDuplicates;
   148      const showCashOrCard = isCardTransaction ? translate('iou.card') : translate('iou.cash');
   149      // We don't use isOnHold because it's true for duplicated transaction too and we only want to show hold message if the transaction is truly on hold
   150      const shouldShowHoldMessage = !(isSettled && !isSettlementOrApprovalPartial) && !!transaction?.comment?.hold;
   151
   152      const [report] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT}${route.params?.threadReportID}`);
   153      const parentReportAction = ReportActionsUtils.getReportAction(report?.parentReportID ?? '', report?.parentReportActionID ?? '');
   154      const reviewingTransactionID = ReportActionsUtils.isMoneyRequestAction(parentReportAction) ? ReportActionsUtils.getOriginalMessage(parentReportAction)?.IOUTransactionID ?? '-1' : '-1';
   155
   156      /*
   157       Show the merchant for IOUs and expenses only if:
   158       - the merchant is not empty, is custom, or is not related to scanning smartscan;
   159       - the expense is not a distance expense with a pending route and amount = 0 - in this case,
   160         the merchant says: "Route pending...", which is already shown in the amount field;
   161      */
   162      const shouldShowMerchant =
   163          !!requestMerchant &&
   164          requestMerchant !== CONST.TRANSACTION.PARTIAL_TRANSACTION_MERCHANT &&
   165          requestMerchant !== CONST.TRANSACTION.DEFAULT_MERCHANT &&
   166          !(isFetchingWaypointsFromServer && !requestAmount);
   167      const shouldShowDescription = !!description && !shouldShowMerchant && !isScanning;
   168
   169      let merchantOrDescription = requestMerchant;
   170      if (!shouldShowMerchant) {
   171          merchantOrDescription = description || '';
   172      }
   173
   174      const receiptImages = hasReceipt ? [{...ReceiptUtils.getThumbnailAndImageURIs(transaction), transaction}] : [];
   175
   176      const getSettledMessage = (): string => {
   177          if (isCardTransaction) {
   178              return translate('common.done');
   179          }
   180          return translate('iou.settledExpensify');
   181      };
   182
   183      const showContextMenu = (event: GestureResponderEvent) => {
   184          if (!shouldDisplayContextMenu) {
   185              return;
   186          }
   187          showContextMenuForReport(event, contextMenuAnchor, reportID, action, checkIfContextMenuActive);
   188      };
   189
   190      const getPreviewHeaderText = (): string => {
   191          let message = showCashOrCard;
   192
   193          if (isDistanceRequest) {
   194              message = translate('common.distance');
   195          } else if (isScanning) {
   196              message = translate('common.receipt');
   197          } else if (isBillSplit) {
   198              message = translate('iou.split');
   199          }
   200
   201          if (isSettled && !iouReport?.isCancelledIOU && !isPartialHold) {
   202              message += ` ${CONST.DOT_SEPARATOR} ${getSettledMessage()}`;
   203              return message;
   204          }
   205
   206          if (shouldShowRBR && transaction) {
   207              const violations = TransactionUtils.getTransactionViolations(transaction.transactionID, transactionViolations);
   208              if (shouldShowHoldMessage) {
   209                  return `${message} ${CONST.DOT_SEPARATOR} ${translate('violations.hold')}`;
   210              }
   211              if (violations?.[0]) {
   212                  const violationMessage = ViolationsUtils.getViolationTranslation(violations[0], translate);
   213                  const violationsCount = violations.filter((v) => v.type === CONST.VIOLATION_TYPES.VIOLATION).length;
   214                  const isTooLong = violationsCount > 1 || violationMessage.length > 15;
   215                  const hasViolationsAndFieldErrors = violationsCount > 0 && hasFieldErrors;
   216
   217                  return `${message} ${CONST.DOT_SEPARATOR} ${isTooLong || hasViolationsAndFieldErrors ? translate('violations.reviewRequired') : violationMessage}`;
   218              }
   219              if (hasFieldErrors) {
   220                  const isMerchantMissing = TransactionUtils.isMerchantMissing(transaction);
   221                  const isAmountMissing = TransactionUtils.isAmountMissing(transaction);
   222                  if (isAmountMissing && isMerchantMissing) {
   223                      message += ` ${CONST.DOT_SEPARATOR} ${translate('violations.reviewRequired')}`;
   224                  } else if (isAmountMissing) {
   225                      message += ` ${CONST.DOT_SEPARATOR} ${translate('iou.missingAmount')}`;
   226                  } else if (isMerchantMissing) {
   227                      message += ` ${CONST.DOT_SEPARATOR} ${translate('iou.missingMerchant')}`;
   228                  }
   229                  return message;
   230              }
   231          } else if (hasNoticeTypeViolations && transaction && !ReportUtils.isReportApproved(iouReport) && !ReportUtils.isSettled(iouReport?.reportID)) {
   232              message += ` • ${translate('violations.reviewRequired')}`;
   233          } else if (ReportUtils.isPaidGroupPolicyExpenseReport(iouReport) && ReportUtils.isReportApproved(iouReport) && !ReportUtils.isSettled(iouReport?.reportID) && !isPartialHold) {
   234              message += ` ${CONST.DOT_SEPARATOR} ${translate('iou.approved')}`;
   235          } else if (iouReport?.isCancelledIOU) {
   236              message += ` ${CONST.DOT_SEPARATOR} ${translate('iou.canceled')}`;
   237          } else if (shouldShowHoldMessage) {
   238              message += ` ${CONST.DOT_SEPARATOR} ${translate('violations.hold')}`;
   239          }
   240          return message;
   241      };
   242
   243      const getPendingMessageProps: () => PendingMessageProps = () => {
   244          if (isScanning) {
   245              return {shouldShow: true, messageIcon: ReceiptScan, messageDescription: translate('iou.receiptScanInProgress')};
   246          }
   247          if (TransactionUtils.isPending(transaction)) {
   248              return {shouldShow: true, messageIcon: Expensicons.CreditCardHourglass, messageDescription: translate('iou.transactionPending')};
   249          }
   250          if (TransactionUtils.hasPendingUI(transaction, TransactionUtils.getTransactionViolations(transaction?.transactionID ?? '-1', transactionViolations))) {
   251              return {shouldShow: true, messageIcon: Expensicons.Hourglass, messageDescription: translate('iou.pendingMatchWithCreditCard')};
   252          }
   253          return {shouldShow: false};
   254      };
   255
   256      const pendingMessageProps = getPendingMessageProps();
   257
   258      const getDisplayAmountText = (): string => {
   259          if (isScanning) {
   260              return translate('iou.receiptScanning');
   261          }
   262
   263          if (isFetchingWaypointsFromServer && !requestAmount) {
   264              return translate('iou.fieldPending');
   265          }
   266
   267          return CurrencyUtils.convertToDisplayString(requestAmount, requestCurrency);
   268      };
   269
   270      const getDisplayDeleteAmountText = (): string => {
   271          const iouOriginalMessage: OnyxEntry<OriginalMessageIOU> = ReportActionsUtils.isMoneyRequestAction(action) ? ReportActionsUtils.getOriginalMessage(action) ?? undefined : undefined;
   272          return CurrencyUtils.convertToDisplayString(iouOriginalMessage?.amount, iouOriginalMessage?.currency);
   273      };
   274
   275      const displayAmount = isDeleted ? getDisplayDeleteAmountText() : getDisplayAmountText();
   276
   277      const shouldShowSplitShare = isBillSplit && !!requestAmount && requestAmount > 0;
   278
   279      // If available, retrieve the split share from the splits object of the transaction, if not, display an even share.
   280      const splitShare = useMemo(
   281          () =>
   282              shouldShowSplitShare
   283                  ? transaction?.comment?.splits?.find((split) => split.accountID === sessionAccountID)?.amount ??
   284                    IOUUtils.calculateAmount(isPolicyExpenseChat ? 1 : participantAccountIDs.length - 1, requestAmount, requestCurrency ?? '', action.actorAccountID === sessionAccountID)
   285                  : 0,
   286          [shouldShowSplitShare, isPolicyExpenseChat, action.actorAccountID, participantAccountIDs.length, transaction?.comment?.splits, requestAmount, requestCurrency, sessionAccountID],
   287      );
   288
   289      const navigateToReviewFields = () => {
   290          const backTo = route.params.backTo;
   291          const comparisonResult = TransactionUtils.compareDuplicateTransactionFields(reviewingTransactionID);
   292          Transaction.setReviewDuplicatesKey({...comparisonResult.keep, duplicates, transactionID: transaction?.transactionID ?? ''});
   293          if ('merchant' in comparisonResult.change) {
   294              Navigation.navigate(ROUTES.TRANSACTION_DUPLICATE_REVIEW_MERCHANT_PAGE.getRoute(route.params?.threadReportID, backTo));
   295          } else if ('category' in comparisonResult.change) {
   296              Navigation.navigate(ROUTES.TRANSACTION_DUPLICATE_REVIEW_CATEGORY_PAGE.getRoute(route.params?.threadReportID, backTo));
   297          } else if ('tag' in comparisonResult.change) {
   298              Navigation.navigate(ROUTES.TRANSACTION_DUPLICATE_REVIEW_TAG_PAGE.getRoute(route.params?.threadReportID, backTo));
   299          } else if ('description' in comparisonResult.change) {
   300              Navigation.navigate(ROUTES.TRANSACTION_DUPLICATE_REVIEW_DESCRIPTION_PAGE.getRoute(route.params?.threadReportID, backTo));
   301          } else if ('taxCode' in comparisonResult.change) {
   302              Navigation.navigate(ROUTES.TRANSACTION_DUPLICATE_REVIEW_TAX_CODE_PAGE.getRoute(route.params?.threadReportID, backTo));
   303          } else if ('billable' in comparisonResult.change) {
   304              Navigation.navigate(ROUTES.TRANSACTION_DUPLICATE_REVIEW_BILLABLE_PAGE.getRoute(route.params?.threadReportID, backTo));
   305          } else if ('reimbursable' in comparisonResult.change) {
   306              Navigation.navigate(ROUTES.TRANSACTION_DUPLICATE_REVIEW_REIMBURSABLE_PAGE.getRoute(route.params?.threadReportID, backTo));
   307          } else {
   308              Navigation.navigate(ROUTES.TRANSACTION_DUPLICATE_CONFIRMATION_PAGE.getRoute(route.params?.threadReportID, backTo));
   309          }
   310      };
   311
   312      const childContainer = (
   313          <View>
   314              <OfflineWithFeedback
   315                  errors={walletTerms?.errors}
   316                  onClose={() => {
   317                      PaymentMethods.clearWalletTermsError();
   318                      Report.clearIOUError(chatReportID);
   319                  }}
   320                  errorRowStyles={[styles.mbn1]}
   321                  needsOffscreenAlphaCompositing
   322                  pendingAction={action.pendingAction}
   323                  shouldDisableStrikeThrough={!isDeleted}
   324                  shouldDisableOpacity={!isDeleted}
   325              >
   326                  <View
   327                      style={[
   328                          isScanning || isWhisper ? [styles.reportPreviewBoxHoverBorder, styles.reportContainerBorderRadius] : undefined,
   329                          !onPreviewPressed ? [styles.moneyRequestPreviewBox, containerStyles] : {},
   330                      ]}
   331                  >
   332                      {hasReceipt && (
   333                          <ReportActionItemImages
   334                              images={receiptImages}
   335                              isHovered={isHovered || isScanning}
   336                              size={1}
   337                          />
   338                      )}
   339                      {isEmptyObject(transaction) && !ReportActionsUtils.isMessageDeleted(action) && action.pendingAction !== CONST.RED_BRICK_ROAD_PENDING_ACTION.DELETE ? (
   340                          <MoneyRequestSkeletonView />
   341                      ) : (
   342                          <View style={[styles.expenseAndReportPreviewBoxBody, hasReceipt ? styles.mtn1 : {}]}>
   343                              <View style={styles.expenseAndReportPreviewTextButtonContainer}>
   344                                  <View style={styles.expenseAndReportPreviewTextContainer}>
   345                                      <View style={[styles.flexRow]}>
   346                                          <Text style={[styles.textLabelSupporting, styles.flex1, styles.lh16]}>{getPreviewHeaderText()}</Text>
   347                                          {!isSettled && shouldShowRBR && (
   348                                              <Icon
   349                                                  src={Expensicons.DotIndicator}
   350                                                  fill={theme.danger}
   351                                              />
   352                                          )}
   353                                      </View>
   354                                      <View style={styles.reportPreviewAmountSubtitleContainer}>
   355                                          <View style={[styles.flexRow]}>
   356                                              <View style={[styles.flex1, styles.flexRow, styles.alignItemsCenter]}>
   357                                                  <Text
   358                                                      style={[
   359                                                          styles.textHeadlineH1,
   360                                                          isBillSplit &&
   361                                                              StyleUtils.getAmountFontSizeAndLineHeight(
   362                                                                  shouldUseNarrowLayout,
   363                                                                  windowWidth,
   364                                                                  displayAmount.length,
   365                                                                  sortedParticipantAvatars.length,
   366                                                              ),
   367                                                          isDeleted && styles.lineThrough,
   368                                                      ]}
   369                                                      numberOfLines={1}
   370                                                  >
   371                                                      {displayAmount}
   372                                                  </Text>
   373                                                  {ReportUtils.isSettled(iouReport?.reportID) && !isPartialHold && !isBillSplit && (
   374                                                      <View style={styles.defaultCheckmarkWrapper}>
   375                                                          <Icon
   376                                                              src={Expensicons.Checkmark}
   377                                                              fill={theme.iconSuccessFill}
   378                                                          />
   379                                                      </View>
   380                                                  )}
   381                                              </View>
   382                                              {isBillSplit && (
   383                                                  <View style={styles.moneyRequestPreviewBoxAvatar}>
   384                                                      <MultipleAvatars
   385                                                          icons={sortedParticipantAvatars}
   386                                                          size="small"
   387                                                          shouldUseCardBackground
   388                                                      />
   389                                                  </View>
   390                                              )}
   391                                          </View>
   392                                          <View style={[styles.flexRow]}>
   393                                              <View style={[styles.flex1]}>
   394                                                  {!isCurrentUserManager && shouldShowPendingConversionMessage && (
   395                                                      <Text style={[styles.textLabel, styles.colorMuted]}>{translate('iou.pendingConversionMessage')}</Text>
   396                                                  )}
   397                                                  {(shouldShowMerchant || shouldShowDescription) && (
   398                                                      <Text style={[styles.textLabelSupporting, styles.textNormal]}>{merchantOrDescription}</Text>
   399                                                  )}
   400                                              </View>
   401                                              {!!splitShare && (
   402                                                  <Text style={[styles.textLabel, styles.colorMuted, styles.ml1, styles.amountSplitPadding]}>
   403                                                      {translate('iou.yourSplit', {amount: CurrencyUtils.convertToDisplayString(splitShare, requestCurrency)})}
   404                                                  </Text>
   405                                              )}
   406                                          </View>
   407                                          {pendingMessageProps.shouldShow && (
   408                                              <View style={[styles.flexRow, styles.alignItemsCenter, styles.mt2]}>
   409                                                  <Icon
   410                                                      src={pendingMessageProps.messageIcon}
   411                                                      height={variables.iconSizeExtraSmall}
   412                                                      width={variables.iconSizeExtraSmall}
   413                                                      fill={theme.icon}
   414                                                  />
   415                                                  <Text style={[styles.textMicroSupporting, styles.ml1, styles.amountSplitPadding]}>{pendingMessageProps.messageDescription}</Text>
   416                                              </View>
   417                                          )}
   418                                      </View>
   419                                  </View>
   420                              </View>
   421                          </View>
   422                      )}
   423                  </View>
   424              </OfflineWithFeedback>
   425          </View>
   426      );
   427
   428      if (!onPreviewPressed) {
   429          return childContainer;
   430      }
   431
   432      const shouldDisableOnPress = isBillSplit && isEmptyObject(transaction);
   433
   434      return (
   435          <PressableWithoutFeedback
   436              onPress={shouldDisableOnPress ? undefined : onPreviewPressed}
   437              onPressIn={() => DeviceCapabilities.canUseTouchScreen() && ControlSelection.block()}
   438              onPressOut={() => ControlSelection.unblock()}
   439              onLongPress={showContextMenu}
   440              shouldUseHapticsOnLongPress
   441              accessibilityLabel={isBillSplit ? translate('iou.split') : showCashOrCard}
   442              accessibilityHint={CurrencyUtils.convertToDisplayString(requestAmount, requestCurrency)}
   443              style={[
   444                  styles.moneyRequestPreviewBox,
   445                  containerStyles,
   446                  shouldDisableOnPress && styles.cursorDefault,
   447                  (isSettled || ReportUtils.isReportApproved(iouReport)) && isSettlementOrApprovalPartial && styles.offlineFeedback.pending,
   448              ]}
   449          >
   450              {childContainer}
   451              {isReviewDuplicateTransactionPage && !isSettled && !isApproved && shouldShowKeepButton && (
   452                  <Button
   453                      text={translate('violations.keepThisOne')}
   454                      success
   455                      style={styles.p4}
   456                      onPress={navigateToReviewFields}
   457                  />
   458              )}
   459          </PressableWithoutFeedback>
   460      );
   461  }
   462
   463  MoneyRequestPreviewContent.displayName = 'MoneyRequestPreview';
   464
   465  export default MoneyRequestPreviewContent;

1  import React, {memo, useMemo} from 'react';
     2  import type {ImageStyle, StyleProp, ViewStyle} from 'react-native';
     3  import {View} from 'react-native';
     4  import type {ValueOf} from 'type-fest';
     5  import useStyleUtils from '@hooks/useStyleUtils';
     6  import useTheme from '@hooks/useTheme';
     7  import useThemeStyles from '@hooks/useThemeStyles';
     8  import * as ReportUtils from '@libs/ReportUtils';
     9  import type {AvatarSource} from '@libs/UserUtils';
    10  import variables from '@styles/variables';
    11  import CONST from '@src/CONST';
    12  import type {Icon} from '@src/types/onyx/OnyxCommon';
